PACKAGES=[
 dict(id='PRE-C02',level='pre-a1',title='Um sábado no bairro',after=['LEX-PRE-27','LEX-PRE-28','LEX-PRE-29','LEX-PRE-30'],
 intro='Leia um pequeno mapa e um pedido, escolha uma atividade e confira quantidade/preço com apoio. Use palavras, apontar e blocos; não exigir parágrafo.',
 reading='''Mapa: A — park; B — shop; C — pharmacy; D — exit.

Cartaz: Saturday. Music in the park. Morning. Choose music or a game.

Pedido de mesa: Rui — one plate, one spoon; Eva — one plate, one fork. Knife: picture only.

Etiqueta fictícia: one cup — 1 credit 25 cents; two cups — total 2 credits 50 cents. One credit = 100 cents.''',
 questions=[('Onde há música e em qual período?','No parque, sábado de manhã.'),('Qual letra identifica farmácia?','C.'),('Quantos pratos no pedido da mesa?','Dois; um para Rui e outro para Eva.'),('Dois copos custam 2.50 cada ou no total?','2.50 no total; 1.25 cada, conforme etiqueta.')],
 explanation='Escolha não é quantidade: music/game são alternativas, one/two indicam quantos. Para combinar dezenas use fifty + two = fifty-two; apoio:57 fifty-seven,68 sixty-eight,79 seventy-nine,86 eighty-six,95 ninety-five. Confira números trocados em duas colunas antes de corrigir.',
 practice=[('Com apoio da tabela, escreva sixty + four como número e palavra.','64, sixty-four.'),('Um colega anota total 250 credits para 2 credits 50 cents. Corrija com os dois campos.','2 credits; 50 cents. Total 2.50, na moeda decimal fictícia.')],
 audio='Hello. My name is Eva. I like music. The park, please. One cup, please. Thank you.',
 audio_questions=[('Nome?','Eva.'),('Preferência e lugar?','Música, parque.'),('Quantidade do pedido?','Um copo.')],
 use='Em dupla, A escolhe music/game e informa place park/home, day Saturday/Sunday e quantity one/two cups. B preenche ficha e repete o pedido. Preços de apoio: one cup 1 credit 25 cents; two cups total 2 credits 50 cents. Troquem com outros dados da mesma lista. Autônomo: cubra sua ficha depois de preenchê-la, diga os blocos e compare; registrar ensaio. Explique o pedido em português sem inventar hora exata.',
 model='Exemplo possível: Music, please. Park, Saturday morning. Two cups, please. Total: two credits, fifty cents. O receptor registra escolha, lugar, dia e quantidade reais do cartão; modelo não é única resposta.',
 phon='Diga 64 e 46 com tabela como apoio; receptor aponta qual ouviu. Preserve a ordem das dezenas. Para plate/spoon/fork, use desenho e confirme o objeto reconhecido; inteligibilidade, não sotaque.',
 teacher='Distribua mapas e preços em cartões; 30–45 minutos como estimativa inicial. Não mostrar dados escolhidos por A a B antes da tentativa. Leia roteiro sem nomear respostas. Peça repetição e confirmação. Em autonomia, não classificar escrita como interação. Utensílios só em imagem; contatos e dinheiro fictícios.',
 review='No encontro seguinte: mapa A shop, B exit, C park, D pharmacy; Sunday games in the park; Rui pede two spoons. Registre lugar da atividade, letra da farmácia, dia e quantidade. Leia 73 com apoio seventy + three. Depois de dois outros encontros, troque letras e recupere novamente.',
 review_answer='Atividade parque C, farmácia D, domingo, duas colheres;73 seventy-three. Letras são as do novo mapa, não as da leitura inicial.',
 assessment='Situação nova: mapa A pharmacy, B park, C shop, D exit. Monday morning: music in the park. Kim requests one plate and two forks. Preço fictício de two cups: total 3 credits 20 cents. Faça ficha em português ou blocos ingleses; depois explique lugar/dia/utensílios/total. Parceiro dita sixty-seven; você registra e confirma, sem parceiro esta parte fica não observada. Não inferir preço de cada copo a partir do total sem conta explicitada.',
 assessment_answer='B parque, segunda de manhã, um prato e dois garfos, total3.20;67 sixty-seven. Não trocar cents por unidades. Oral só avaliado se a fala foi efetivamente compreendida.'),
 dict(id='A1-C02',level='a1',title='Convite, cardápio e passeio',after=['LEX-A1-22','LEX-A1-23','LEX-A1-24','LEX-A1-25','LEX-A1-26'],
 intro='Ler mensagem pessoal, cardápio e aviso; pedir informação e responder a convite com uma razão. Apoio: until = até; bring = traga; either = qualquer um dos dois neste recado.',
 reading='''Hi Jo! I am in a small town this weekend. It is cool and foggy this morning. The museum is open from ten until four on Saturday and closed on Sunday. Would you like to visit it on Saturday? We can have lunch at the café. I like fish, but there is chicken too. Bring an umbrella. Kim.

Café: chicken with rice — 6 credits; fish with vegetables — 7 credits; fruit — 2 credits; tea — 1 credit. Cards accepted. Pay at the checkout. Tea with or without sugar. Rice without salt: ask first.

Jo's reply: I work until noon on Saturday. I can meet at one. Is that too late? I am free on Sunday, but the museum is closed then.''',
 questions=[('Jo pode visitar sábado de manhã?','Não antes de meio-dia, porque trabalha até noon.'),('Às13h o museu está dentro do horário informado?','Sim; abre10, fecha16 no sábado. Isso não reserva ingresso.'),('Quanto custa fish + tea? Conta de apoio7+1=8.','Oito créditos.'),('Arroz sem sal está garantido?','Não; é preciso perguntar.'),('Domingo livre de Jo resolve visita ao museu?','Não; museu fechado domingo.')],
 explanation='Present simple apresenta horário/rotina; can indica disponibilidade possível. Use because para razão e but para contraste: I am free on Sunday, but the museum is closed. Pedido com Can I...? não é confirmação de disponibilidade.',
 practice=[('Complete resposta usando because: I cannot meet at ten ___ I work until noon.','Because.'),('Preço8, pagamento em espécie10, conta10−8=2. Pergunte meio de pagamento e confira troco se espécie aceita.','Can I pay in cash? My change is two credits. Aceitação de cash não está na placa cards accepted; perguntar antes.')],
 audio='Hi Jo. Saturday at one is fine. Let us meet outside the museum. I will have chicken with rice and tea without sugar. Could you check if we can pay in cash?',
 audio_questions=[('Hora e ponto de encontro?','Sábado13h, fora do museu.'),('Pedido de Kim?','Frango com arroz e chá sem açúcar.'),('Qual informação precisa conferir?','Se aceitam pagamento em espécie.')],
 use='Escreva resposta de45–65palavras a Kim: confirme a disponibilidade de Jo, lugar e hora sugeridos, faça uma pergunta sobre comida ou pagamento e dê uma razão. Em dupla, atendente só pode responder dados do menu; no que não sabe, pede para conferir. Autônomo: produza pedido e resposta prevista, marcando informação desconhecida. Depois explique aviso do museu em português a um visitante.',
 model='Hi Kim. Saturday at one is good because I finish work at noon. We can meet outside the museum. I would like fish with vegetables and tea without sugar. Can I pay in cash? I also want to ask about rice without salt. See you on Saturday. Sunday does not work for the museum because it is closed.',
 phon='Confirme 13:00 versus15:00 com registro escrito e destaque WITHOUT no pedido. Aceitar leituras one in the afternoon e thirteen hundred se compreensíveis, sem exigir ambas.',
 teacher='45–60minutos previstos, medir. Distribuir menu e mensagem separadamente. Fazer leitura individual antes de conversa; não inventar regra de pagamento. Trabalhar because/but em razão e contraste, não só preencher lacuna. Roteiro oral após perguntas lidas. Recusa e pergunta educada são resultados válidos.',
 review='Próximo encontro: museum open Sunday11–15, closed Saturday. Jo free Sunday after12; café fish8, tea2; cards only. Faça novo convite com hora viável e pedido de dois itens; conta8+2=10. Após dois outros encontros, introduza chuva prevista e pergunte sobre lugar coberto sem afirmar que existe.',
 review_answer='Domingo entre12e15 é janela possível; sábado fechado. Modelo: Shall we meet at one on Sunday? Fish and tea total10; somente cartão. Área coberta permanece pergunta, não fato.',
 assessment='Nova mensagem: museum open Friday12–18, closed weekend. Lee works until14 Friday; Kim free from15. Café chicken5, vegetables3, tea2; cash only; sugar optional. Proponha encontro de45–65palavras com hora comum, pedido e pergunta pertinente. Conta chicken+tea=7; entrega10, troco3. Medeie horários em português. Interação em dupla: colega não ouviu hora e pede repetição; repita e confirme, ou marque não observado se sozinho.',
 assessment_answer='Sexta a partir15 antes18; fim de semana não serve. Exemplo15:30. Frango+chá7, espécie, troco3 ao pagar10. Sugar optional exige escolha/pedido, não presume açúcar. Pergunta pode ser localização ou outra informação não fornecida. Repetição oral depende de execução.'),
 dict(id='A2-C02',level='a2',title='Blog de viagem e instruções para participar',after=['LEX-A2-21','LEX-A2-22','LEX-A2-23','LEX-A2-24'],
 intro='Ler um relato pessoal e um procedimento, reformular pontos obscuros e produzir mensagem sem roteiro completo. Apoio: coast = litoral; childhood = infância; uploaded = enviado a um serviço; download é direção contrária.',
 reading='''I grew up in a town near the coast. During my childhood, I used to walk to school with my cousin. Last year I moved abroad. I still call that town my hometown, although I do not live there now. Last weekend I joined a local walking group. We got lost near a museum, asked a resident for directions and reached the meeting late. I enjoyed the walk, but next time I will check the route first. Lia.

Group notice: Residents and visitors can join. Sign up for Saturday's workshop; places will be confirmed on Thursday. A donation of books is optional. To prepare: download the worksheet, write a fictional name, save the file. Restart the tablet only after saving if the practice instruction asks you to. No real account is required.''',
 questions=[('Onde Lia cresceu? Sabemos nome da cidade?','Perto do litoral; nome não informado.'),('Ela mora atualmente na hometown?','Não.'),('Por que chegou tarde segundo relato?','Grupo se perdeu perto do museu; pediu orientação a morador.'),('Inscrever-se confirma vaga imediatamente?','Não; confirmação quinta.'),('Doação é obrigatória?','Não, opcional.'),('Qual direção de download e qual ordem antes de restart?','Serviço para dispositivo; salvar antes de reiniciar, se instrução pedir.')],
 explanation='Used to + verbo apresenta hábito antigo; passado simples narra último fim de semana. Reformulação precisa esclarecer uma dúvida real: Do you mean...? / What I mean is... . No procedimento, before/after mudam ordem; não ler todos os passos como simultâneos.',
 practice=[('Lia says moved abroad last year. Reescreva sem inventar país.','She moved to another country last year.'),('Repare Please explain me the rule.','Please explain the rule to me; Could you explain the rule? também vale.'),('Tablet já ligado e ficha já baixada. Quais passos ainda não podem ser presumidos feitos?','Preencher nome fictício e salvar; reiniciar só se solicitado. Não repetir download como necessário.')],
 audio='I signed up for the workshop, but I am not sure if I have a place. Do you mean that I should wait until Thursday? And could you explain the donation rule? I have two books, but I cannot give money.',
 audio_questions=[('A pessoa tem vaga confirmada?','Não sabe; apenas inscreveu-se.'),('Quais duas dúvidas apresenta?','Esperar até quinta e regra da doação.'),('O que pode doar e o que não pode?','Dois livros, não dinheiro.')],
 use='Sem copiar o texto, escreva80–110palavras sobre uma experiência fictícia em passeio: situação inicial, problema, ajuda recebida, resultado e plano diferente para próxima vez. Inclua um contraste entre hábito antigo e situação atual se fizer sentido. Em dupla, o parceiro pergunta por uma informação que você omitiu; responda coerentemente ou diga que não foi definida no personagem. Autônomo: releia como destinatário e escreva duas perguntas ainda abertas. Depois redija recado curto ao grupo sobre inscrição e doação.',
 model='I used to walk around my hometown with my cousin. Last month I visited another town and joined a walking group. We took the wrong road near a museum, so we asked a resident for help. We arrived late, but the group was still there. I enjoyed the walk. Next time I will check the map before leaving. I have also signed up for the workshop. I will wait for confirmation on Thursday. Could you explain where I can leave my book donation?',
 phon='Organize narrativa em blocos com pausa entre contexto, problema e resultado. Destaque before/after na sequência; o parceiro ordena cartões após ouvir. Não avaliar fluência por falar sem respirar.',
 teacher='50–75minutos previstos. Gêneros: blog e instrução. Não dar todos os fatos na produção livre; aceitar personagem fictício consistente. Ensino antes da tarefa inclui reparar explain...to e distinguir register/confirmed. Cartão de inscrição não exige login real. Na escuta, não tratar pergunta do narrador como resposta já obtida.',
 review='Encontro seguinte: personagem nasceu em Recife, cresceu em Natal, mudou para Lisboa, não casou ainda; costumava jogar no parque, agora corre na praia. Escreva perfil de60–90palavras sem confundir nascimento/hometown presumida. Aviso novo confirma vagas sexta e pede doação opcional de roupa, não livros. Explique diferenças. Após dois outros encontros, conte experiência fictícia de lazer com um contratempo e solução.',
 review_answer='Born Recife, grew up Natal, moved abroad to Lisbon; casamento não ocorrido. Hometown depende da identificação do personagem, não inferir automaticamente. Used to play in park, now runs on beach. Confirmação sexta; roupa opcional, não reaproveitar quinta/livros do primeiro aviso.',
 assessment='Texto novo: “I used to live in a village. I moved to another city in the same country last year. Yesterday I joined a museum tour. The entrance was difficult to find, but a resident showed me the way. I arrived on time.” Aviso: workshop next Tuesday; sign up by Friday; confirmation Monday; books optional. Produza resumo de70–100palavras e mensagem com duas perguntas de informação ausente. Explique por que mudança não é necessariamente abroad. Procedimento em desenho: file already downloaded, changes not saved; next step save before restart. Depois conte experiência fictícia própria de lazer, sem copiar fatos do texto.',
 assessment_answer='Morava em vila, mudou de cidade no mesmo país ano passado, visita guiada ontem, morador ajudou, chegou pontualmente; não abroad. Inscrição até sexta, confirmação segunda, oficina terça, livros opcionais. Perguntas válidas: hora/lugar da oficina ou onde doar. Salvar alterações antes de reiniciar; download já feito. Relato livre avaliado por sequência/coerência/clareza, não igualdade a modelo.'),
 dict(id='B1-C02',level='b1',title='Notícia, conto e escolha fundamentada',after=['LEX-B1-21','LEX-B1-22','LEX-B1-23','LEX-B1-24','LEX-B1-25'],
 intro='Comparar gêneros e sustentar opinião sem apagar fonte, incerteza ou contraponto. Há notícia fictícia e conto autoral; nenhum é relato real. Produção oral pode ser gravada para revisão, sem inferir interação por gravação individual.',
 reading='''NEWS BRIEF — Tuesday. Headline: PARK CLEAN-UP SOLVES POLLUTION. Volunteers removed litter from one path on Monday. Twenty boxes of paper were collected for recycling, but processing has not been checked. The council is considering renewable energy for a building. No air measurements were included in the report. A resident said, “The path looks better.”

SHORT STORY — The Blue Coat. I bought the coat because it was cheap. Its brand meant nothing to me, but a note in the pocket did: “For the next journey.” On the train I noticed the cuffs were worn out. At the next station, an older passenger smiled and asked where I had found it. Before I could answer, the doors opened and she stepped out. I still have the coat. I never learned who wrote the note.''',
 questions=[('Manchete é sustentada pelo corpo?','Não estabelece solução para toda poluição; relata limpeza de um caminho e ausência de medições do ar.'),('Reciclagem concluída e energia instalada?','Não; coleta com destino pretendido, processamento não verificado; energia em consideração.'),('Qual setting conhecido no conto?','Trem/estações, época não informada; não inventar cidade.'),('O narrador sabe quem escreveu bilhete?','Não.'),('A senhora é dona anterior comprovada?','Não; sorriso e pergunta não provam isso.'),('Durabilidade é demonstrada pela marca?','Não; marca não significa nada para narrador e punhos estão gastos.')],
 explanation='Notícia: separar fonte e alcance com reports, according to e no evidence provided. Conto: narrador conhece apenas o que relata; hipóteses precisam de might/perhaps. Opinião: critério → vantagem → contraponto → conclusão condicionada; in my opinion não elimina necessidade de justificar. Para pronúncia, a pausa deve preservar qual fonte disse o quê.',
 practice=[('Reescreva Recycling completed usando apenas notícia.','Paper was collected for recycling, but processing has not been verified.'),('Reescreva The older passenger wrote the note como hipótese.','Perhaps the older passenger wrote the note; autoria não confirmada.'),('Compare cheap coat20 + repair15 e new coat40, custos totais fornecidos35/40. Marca sem teste.','The second-hand coat costs35 including repairs, compared with40 for the new one. Durability is unknown; cannot decide from brand alone.')],
 audio='I thought the coat was a bargain at first. On balance, I still like it, although the repairs cost more than I expected. The ending of the story surprised me. I tend to prefer clear answers, but this time I enjoyed not knowing who wrote the note. I would recommend discussing two possible explanations rather than choosing one as a fact.',
 audio_questions=[('A opinião sobre casaco é inteiramente negativa?','Não; ainda gosta, apesar de reparos caros.'),('O leitor sempre prefere finais abertos?','Não; tende a preferir respostas claras, mas gostou deste.'),('Qual recomendação faz?','Discutir duas explicações possíveis sem escolher uma como fato.')],
 use='Faça fala de2–3minutos para um clube de leitura: resuma conto, explique reação ao final, apresente duas interpretações com evidências e limite. Colega faz pergunta não ensaiada e você responde. Depois escreva correção de120–160palavras para a manchete da notícia, distinguindo ações feitas, propostas e dados ausentes. Autônomo: grave fala, reveja onde transformou hipótese em certeza; interação continua não observada. Como tarefa de decisão, compare dois passeios: parque gratuito com chuva prevista e cobertura desconhecida; museu10créditos com elevador, fecha17h. Grupo precisa16–18h e acesso sem escadas. Recomende perguntas antes da escolha.',
 model='Modelo de abertura oral: “The plot follows a person who buys a second-hand coat and finds a note. The narrator never discovers who wrote it. The older passenger might know something about the coat, but the text does not confirm that. I found the ending unexpected because the conversation stops just when an answer seems possible.” Notícia: limitar conclusão à limpeza observada, coleta destinada a reciclagem, energia em estudo e medições ausentes. Decisão: nenhuma opção atende todos os critérios confirmados; conferir extensão de horário, cobertura e acesso do parque.',
 phon='Destaque might e not confirmed; faça pausa antes de mudar de notícia para conto. O parceiro marca qual afirmação é relato/opinião/hipótese. Trabalhe contraste asked/answered apenas se dificultar a compreensão, sem exigir acento nativo.',
 teacher='60–90minutos previstos em um ou dois encontros. Gêneros distintos evitam treinar apenas aviso institucional. Perguntas não ensaiadas devem se limitar ao texto/produção, sem interrogar vida pessoal. Leia roteiro depois de perguntas; não revelar transcrição de início. Feedback primeiro sobre alcance e tarefa, depois uma questão de forma. Para autonomia, gravação individual permite autorrevisão, não substitui interação real.',
 review='Encontro seguinte: manchete New centre opens; corpo diz plan approved, opening date unknown. Conto termina com personagem prestes a abrir envelope, conteúdo não revelado. Redija correção curta da manchete e duas hipóteses para envelope. Compare casaco usado15 + reparo30 e novo40 com soma45fornecida; reavalie bargain. Após dois encontros, faça nova fala com uma objeção levantada pelo parceiro.',
 review_answer='Centro aprovado, data desconhecida; não aberto. Conteúdo do envelope desconhecido, hipóteses marcadas. Usado custa45com reparo versus40novo, logo preço inicial menor não garante menor total; outros critérios podem importar. Objeção real precisa de registro do interlocutor.',
 assessment='Notícia inédita: headline River is clean; report says volunteers collected litter beside one bridge; no water tests supplied; future wildlife survey proposed, not started. Conto inédito: “On the bus I found a ticket dated tomorrow. A child said it belonged to her brother. Before I could ask his name, they left. I kept the ticket at the information desk.” Produza correção de120–160palavras da notícia e fala de2–3minutos sobre conto, incluindo setting, plot, duas interpretações e limites. Compare excursões: A custa20,tem acesso sem escada,termina16; B custa15,acesso desconhecido,termina18. Grupo precisa terminar17e acesso. Recomende com ressalvas. Parceiro faz pergunta de seguimento; sozinho marque interação não observada.',
 assessment_answer='Limpeza ao lado de uma ponte não prova qualidade da água; sem testes, pesquisa futura não iniciada. Conto ônibus, bilhete datado amanhã, criança atribui ao irmão, nome desconhecido, bilhete deixado na informação; não afirmar mentira/fraude/viagem no tempo como fato. Opção A atende horário e acesso informados, custa mais; B excede término e acesso incerto. Produção avaliada por fidelidade, organização, justificativa, linguagem compreensível e reparo real; não há única interpretação literária correta.')
]
